<script>
document.addEventListener('DOMContentLoaded', () => {
    const form = document.querySelector('form[action*="numbering-rules"]');
    if (form) {
        const code = form.querySelector('input[name="form_key"]'), name = form.querySelector('input[name="name"]');
        if (code && name) { const select = document.createElement('select'); select.name = 'form_key'; select.className = 'form-select'; select.required = true; [['hris_overtime','Pengajuan Lembur'],['hris_leave','Pengajuan Cuti'],['hris_claim','Pengajuan Claim'],['hris_employee_document','Dokumen Karyawan']].forEach(([key,label]) => { const option = new Option(`${label} (${key})`, key); if (code.value === key) option.selected = true; select.add(option); }); code.parentElement.replaceWith(Object.assign(document.createElement('div'), {className:'col-md-2'})); const holder = form.querySelector('div.col-md-2'); holder.innerHTML = '<label class="form-label">Jenis form</label>'; holder.appendChild(select); name.closest('.col-md-3')?.remove(); }
        const help = document.createElement('button'); help.type = 'button'; help.className = 'btn btn-link btn-sm p-0 ms-2'; help.textContent = 'Bantuan pola'; help.dataset.bsToggle = 'modal'; help.dataset.bsTarget = '#patternHelp'; form.querySelector('input[name="format"]')?.previousElementSibling?.appendChild(help);
        const editLinks = [...document.querySelectorAll('.mt-3 a[href*="numbering-rules"]')]; document.querySelectorAll('table tbody tr').forEach((row, index) => { if (editLinks[index]) { const link = editLinks[index].cloneNode(true); link.className = 'btn btn-sm btn-outline-primary me-1'; link.textContent = 'Edit'; row.querySelector('td:last-child')?.prepend(link); } });
    }
});
</script>
